import { APPLICATION_ACTION } from './actions'

export const INITIAL_STATE = {}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case APPLICATION_ACTION.COLLECTION_DETAIL:
    case APPLICATION_ACTION.IMPORT_COLLECTION:
    case APPLICATION_ACTION.EXPORT_COLLECTION:
    case APPLICATION_ACTION.GET_COLLECTION_LIST:
    case APPLICATION_ACTION.CLEAR_RECORDS:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
