import { urls } from '../config/url'

const { getCollections, getCollectionDetail, importCollection, exportCollection, clearRecordApi } = urls

export const APPLICATION_ACTION = {

  GET_COLLECTION_LIST_REQUEST: 'GET_COLLECTION_LIST_REQUEST',
  GET_COLLECTION_LIST: 'GET_COLLECTION_LIST',

  IMPORT_COLLECTION_REQUEST: 'IMPORT_COLLECTION_REQUEST',
  IMPORT_COLLECTION: 'IMPORT_COLLECTION',

  EXPORT_COLLECTION_REQUEST: 'EXPORT_COLLECTION_REQUEST',
  EXPORT_COLLECTION: 'EXPORT_COLLECTION',

  COLLECTION_DETAIL_REQUEST: 'COLLECTION_DETAIL_REQUEST',
  COLLECTION_DETAIL: 'COLLECTION_DETAIL',

  CLEAR_RECORDS_REQUEST: 'CLEAR_RECORDS_REQUEST',
  CLEAR_RECORDS: 'CLEAR_RECORDS'

}

export const getTotalCollections = (payload) => ({
  type: APPLICATION_ACTION.GET_COLLECTION_LIST_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: getCollections
  }
})

export const getCollectionDetails = (payload) => ({
  type: APPLICATION_ACTION.COLLECTION_DETAIL_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: getCollectionDetail
  }
})

export const downloadCollection = (payload) => ({
  type: APPLICATION_ACTION.EXPORT_COLLECTION_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: exportCollection
  }
})

export const uploadCollecion = (payload) => ({
  type: APPLICATION_ACTION.IMPORT_COLLECTION_REQUEST,
  payload: {
    ...payload,
    method: 'POST',
    url: importCollection
  }
})

export const clearRecords = (payload) => ({
  type: APPLICATION_ACTION.CLEAR_RECORDS_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: clearRecordApi
  }
})
