/* eslint-disable react-hooks/exhaustive-deps */
import { useCallback, useEffect, useState, useMemo } from 'react'
import { Button, Upload, Icon, Tag } from 'antd'
import { useLoaderContextValue, useErrorContextValue, updateLoader, resetError } from '@pasarpolis/common-react-hooks'
import TableWrapper from './tableWrapper'
import CircularLoader from '../../../../../../components/CircularLoader'
import { showNotification } from '../../../../../../components/ShowNotification'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { FilterInput } from '../../../../../../components/tables/helperCells'
import { TableDisplay } from './index.style'
import {
  useCollectionListData,
  useExportCollectionData,
  useImportCollectionData
} from '../../../state/hook/useApplicationState'

const fileDownload = require('js-file-download')

function MappingCollectionData (props) {
  const [{
    GET_COLLECTION_LIST_LOADER,
    IMPORT_COLLECTION_LOADER,
    EXPORT_COLLECTION_LOADER
  }, dispatchLoader] = useLoaderContextValue()

  const [{
    getCollectionListStatus,
    exportCollectionStatus,
    EXPORT_COLLECTION_ERROR,
    exportCollectionErrorData,
    IMPORT_COLLECTION_ERROR,
    importCollectionErrorData,
    importCollectionStatus,
  }, dispatchError] = useErrorContextValue()

  const isLoaderActive = (GET_COLLECTION_LIST_LOADER || IMPORT_COLLECTION_LOADER || EXPORT_COLLECTION_LOADER)

  const [pageState, getCollectionListDataRequest] = useCollectionListData()
  const [exportState, getExportedData] = useExportCollectionData()
  const [, getImportDataRequest] = useImportCollectionData()

  const [searchTextQuery, setSearchTextQuery] = useState({})
  const [appliedFilter, setAppliedFilter] = useState({})
  const [showSearch, setShowSearch] = useState('')
  const [filteredList, setFilteredList] = useState([])

  const [state, setState] = useState({
    collectionList: []
  })

  // To get the list of collections and display
  useEffect(() => {
    getCollectionListDataRequest({})
  }, [])

  useEffect(() => {
    if (getCollectionListStatus === 'success') {
      const dataSource = []
      
      if(pageState.getCollectionListData) {
        for(const collectionName in pageState.getCollectionListData) {
          dataSource.push({
            collection_id: [collectionName, pageState.getCollectionListData[collectionName]],
            collection_name: collectionName,
            collection_count: pageState.getCollectionListData[collectionName],
            import: collectionName,
            export: collectionName
          })    
      }}  

      dispatchError(resetError({
        getCollectionListStatus: undefined
      }))
      setState((prevState) => ({
        ...prevState,
        collectionList: dataSource
      }))
      setFilteredList(dataSource)
    }
  }, [getCollectionListDataRequest, dispatchError, dispatchLoader, getCollectionListStatus])

  // handled export functionality
  const handleExportFunction = useCallback((collection) => {
    
    if (!EXPORT_COLLECTION_LOADER) {
      getExportedData({
        query: {
          collection
        }
      })
    }
  }, [getExportedData, EXPORT_COLLECTION_LOADER])

  useEffect(() => {
    if (exportCollectionStatus === 'success') {
      fileDownload(JSON.stringify(exportState.exportCollectionData), 'data.json')
      showNotification('success', "Successfully Exported")


      dispatchLoader(updateLoader({
        EXPORT_COLLECTION_LOADER: undefined
      }))
      dispatchError(resetError({
        exportCollectionStatus: undefined
      }))

    } else if (EXPORT_COLLECTION_ERROR) {
      if(exportCollectionErrorData?.error){
        showNotification('error', exportCollectionErrorData.error)
      } else if(exportCollectionStatus) {
        showNotification('error', exportCollectionStatus)
      }
      dispatchError(resetError({
        EXPORT_COLLECTION_ERROR: false
      }))
      dispatchLoader(updateLoader({
        EXPORT_COLLECTION_LOADER: undefined
      }))
    }
  }, [getExportedData, dispatchLoader, dispatchError, EXPORT_COLLECTION_LOADER])

  // Import Functionality Handling  
  const importData = useCallback((val, collectionName) => {
    
    if (!IMPORT_COLLECTION_LOADER) {
      getImportDataRequest({
        query: {
          collection: collectionName
        },
        body: val
      })
    }
  }, [getImportDataRequest, IMPORT_COLLECTION_LOADER])

  const handleImportFunction = (info, collectionName) => {
    const files = info.file
    const reader = new FileReader()

    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target.result)
        importData(data, collectionName)
      } catch (error) {
        if (error?.toString()?.includes('SyntaxError')) {
          showNotification('error', "Invalid json structure")
          return;
        }
        showNotification('error', "Error! Invalid file")
        console.error(error)
      }
    }
    reader.readAsText(files)
  }

  useEffect(
    () => {
      if (IMPORT_COLLECTION_ERROR) {
        if (!!importCollectionErrorData.invalid_records) {
          const value = importCollectionErrorData.invalid_records.length + ' Invalid Records Found'
          showNotification('error', value)
        } else if (!!importCollectionErrorData.error) {
          showNotification('error', importCollectionErrorData.error)
        } else if (!!importCollectionErrorData.message) {
          showNotification('error', importCollectionErrorData.message)
        }
        dispatchError(resetError({
          IMPORT_COLLECTION_ERROR: undefined,
          importCollectionErrorData: {}
        }))
      } else if (importCollectionStatus === 'success') {
        showNotification('success', 'Successfully uploaded')
        dispatchLoader(updateLoader({
          IMPORT_COLLECTION_LOADER: undefined
        }))
        setTimeout(() => {
          window.location.reload()
        }, 1000)
        dispatchError(resetError({
          importCollectionStatus: ''
        }))
      }
    }, [dispatchError, IMPORT_COLLECTION_LOADER]
  )

  const onInputChange = (event, identifier) => {
    setSearchTextQuery({[identifier]: event.target.value})
  }

  const onSearch = () => {
    const { collectionList } = state
    const { collectionName } = searchTextQuery
    const filterList = collectionList?.filter((collection) => {
      return collection.collection_name?.toLocaleLowerCase().includes(collectionName?.toLocaleLowerCase())
    })
    setAppliedFilter({collectionName})
    setShowSearch(false)
    if(filterList.length !== collectionList.length){
      setFilteredList(filterList)
    } 
  }

  const clearFilter = () => {
    setAppliedFilter({})
    setFilteredList(state.collectionList)
  }

  // useMemo
  const columns = useMemo(() => [
    {
      key: 'collection_id',
      title: 'Action',
      dataIndex: 'collection_id',
      render: ([val, len]) => (
        <PermissionCheckerV2 requiredPermission='ops.view_collections_details'>
          <i
            className='far fa-eye'
            style={{
              cursor: 'pointer',
              visibility: len > 0 ? 'visible' : 'hidden'
            }}
            onClick={() => {
              dispatchLoader(updateLoader({
                GET_COLLECTION_LIST_LOADER: undefined
              }))
              props.history.push(`/data-collections/${val}`)
            }}
          />
        </PermissionCheckerV2>
      ),
      align: 'center'
    },
    {
      key: 'collection_name',
      title: 'Collection Name',
      dataIndex: 'collection_name',
      align: 'center',
      filterDropdown: (
        <FilterInput
          idIdentifier='collectionName'
          searchText={searchTextQuery.collectionName}
          onInputChange={e => onInputChange(e, 'collectionName')}
          onSearch={e => onSearch(e, 'collectionName')}
        />
      ),
      filterDropdownVisible: showSearch,
      onFilterDropdownVisibleChange: visible => setShowSearch(visible)
    },
    {
      key: 'collection_count',
      title: 'Collection Count',
      dataIndex: 'collection_count',
      align: 'center'
    },
    {
      key: 'import',
      title: 'Import Collection',
      dataIndex: 'import',
      align: 'center',
      render: val => (
        <PermissionCheckerV2 requiredPermission='ops.import_collections'>
          <Upload
            name='file'
            multiple={false}
            showUploadList={false}
            customRequest={(file) => {
              handleImportFunction(file, val)
            }}
          >
            <Button disabled={false}>
              <Icon type='upload' /> Import
            </Button>
          </Upload> 
        </PermissionCheckerV2>
      )
    },
    {
      key: 'export',
      title: 'Export Collection',
      dataIndex: 'export',
      align: 'center',
      render: val =>
        (
          <PermissionCheckerV2 requiredPermission='ops.export_collections'>
            <Button disabled={false} onClick={() => handleExportFunction(val)}>
              <Icon type='download' /> Export
            </Button>
          </PermissionCheckerV2>
        )

    }
  ])

  return (
    <TableDisplay>
      <CircularLoader isSpining={isLoaderActive}>
        <h2>
          <b>Data Collection</b>
        </h2>
        {appliedFilter?.collectionName && (
          <Tag className="filter-tag" color="volcano">
            Collection Name - {appliedFilter.collectionName}
            <span
              className="remove-filter"
              onClick={(e) => clearFilter("collectionName")}
            >
              X
            </span>
          </Tag>
        )}
        <TableWrapper
          className="table-container"
          columns={columns}
          dataSource={filteredList}
        />
      </CircularLoader>
    </TableDisplay>
  )
}

export default MappingCollectionData
